    for el in root.iter():
        tag = _get_tag_name(el)
        if tag is None:
            continue

        if tag == 'object':
            for link in _handle_object_tag(el):
                yield link
        else:
            for link in _handle_element_links(el):
                yield link

        if not find_links_in_css:
