                    s.settimeout(self.timeout)
            conn = self.ConnectionClass(self, s, makefile)
            if not isinstance(self.bind_addr, basestring):
                if addr is None:
                    if len(s.getsockname()) == 2:
                        addr = ('0.0.0.0', 0)
                    else:
                        addr = ('::', 0)
                conn.remote_addr = addr[0]
                conn.remote_port = addr[1]
