        for elem in refines[item_id]:
            key = elem.get('property')
            if key:
                val = (elem.text or '').strip()
                if val:
                    ans[key] = val
    return ans


def _parse_scheme(scheme, prefixes):
    if not scheme:
        return None, None
    if ':' not in scheme:
        return None, scheme
    p, r = scheme.split(':', 1)
    ns = prefixes.get(p)
    if ns:
        return ns, r
    return None, scheme


