    ans = {}
    for elem in refines.get(item_id, []):
        key = elem.get('property')
        if not key:
            continue
        val = (elem.text or '').strip()
        if not val:
            continue
        scheme = elem.get('scheme')
        scheme_ns, scheme_val = _parse_scheme(scheme, prefixes)
        ans[key] = (scheme_ns, scheme_val, val)
    return ans


