        return _re_cache[(r, flags)]
    except KeyError:
        _re_cache[(r, flags)] = ans = re.compile(r, flags)
        return ans


def remove_refines(e, refines):
    for x in refines[e.get('id')]:
        x.getparent().remove(x)
    refines.pop(e.get('id'), None)


def remove_element(e, refines):
    remove_refines(e, refines)
    e.getparent().remove(e)


def properties_for_id(item_id, refines):
    ans = {}
    if item_id:
        for elem in refines[item_id]:
            key = elem.get('property')
            if key:
                val = (elem.text or '').strip()
                if val:
                    ans[key] = val
    return ans


def _parse_scheme(scheme, prefixes):
    """Parse a scheme string into (namespace, local_name) tuple."""
    if scheme is None:
        return None, None
    p, r = scheme.partition(':')[::2]
    if not (p and r):
        return None, None
    ns = prefixes.get(p)
    if ns:
        return ns, r
    return None, None


def properties_for_id_with_scheme(item_id, prefixes, refines):
    """
    Return a mapping of property names to a tuple of
    (namespace, scheme, value) for the given item id.
    """
    ans = {}
    if not item_id:
        return ans
    for elem in refines.get(item_id, []):
        key = elem.get('property')
        if not key:
            continue
        val = (elem.text or '').strip()
        if not val:
            continue
        scheme = elem.get('scheme')
        scheme_ns, scheme_local = _parse_scheme(scheme, prefixes)
        ans[key] = (scheme_ns, scheme_local, val)
    return ans


