# Utils {{{
_xpath_cache = {}
_re_cache = {}


def uniq(vals):
    ''' Remove all duplicates from vals, while preserving order.  '''
    vals = vals or ()
    seen = set()
    seen_add = seen.add
    return list(x for x in vals if x not in seen and not seen_add(x))


def dump_dict(cats):
    return json.dumps(object_to_unicode(cats or {}), ensure_ascii=False, skipkeys=True)


def XPath(x):
    try:
        return _xpath_cache[x]
    except KeyError:
        _xpath_cache[x] = ans = etree.XPath(x, namespaces=OPF2_NSMAP)
        return ans


def regex(r, flags=0):
    try:
        return _re_cache[(r, flags)]
    except KeyError:
        _re_cache[(r, flags)] = ans = re.compile(r, flags)
        return ans


def remove_refines(e, refines):
    for x in refines[e.get('id')]:
        x.getparent().remove(x)
    refines.pop(e.get('id'), None)


def remove_element(e, refines):
    remove_refines(e, refines)
    e.getparent().remove(e)


def properties_for_id(item_id, refines):
    ans = {}
    if item_id:
        for elem in refines[item_id]:
            key = elem.get('property')
            if key:
                val = (elem.text or '').strip()
                if val:
                    ans[key] = val
    return ans


def _parse_scheme(elem, prefixes):
    """
    Parse the scheme attribute of a meta element.

    Returns a tuple (scheme_ns, scheme) where scheme_ns is the namespace
    associated with the prefix, or None if not applicable, and scheme is
    the local part of the scheme. If the scheme attribute is missing or
    malformed, scheme_ns is None and scheme is the original scheme string.
    """
    scheme = elem.get('scheme')
    if scheme is None:
        return None, None
    p, r = scheme.partition(':')[::2]
    if not (p and r):
        return None, scheme
    ns = prefixes.get(p)
    if ns:
        return ns, r
    return None, scheme


def properties_for_id_with_scheme(item_id, prefixes, refines):
    if not item_id:
        return {}
    ans = {}
    for elem in refines[item_id]:
        key = elem.get('property')
        if not key:
            continue
        val = (elem.text or '').strip()
        if not val:
            continue
        scheme_ns, scheme = _parse_scheme(elem, prefixes)
        ans[key] = (scheme_ns, scheme, val)
    return ans


